<div class="page-heading"><div><div class="eyebrow">ENTREGA E MONTAGEM</div><h1>Instalações</h1><p>Agendamento das equipes e checklists de montagem.</p></div><div class="page-actions"><a href="<?=e(url('installations',['new'=>1]))?>#editor" class="btn-aurora"><?=svg_icon('plus',16)?> Agendar instalação</a></div></div>
<?php if(allow(['production'])):?><details class="panel editor" id="editor" <?=($edit||isset($_GET['new']))?'open':''?>><summary><?=$edit?'Editar agendamento':'Nova instalação'?></summary><div class="editor-inner"><form action="<?=e(url('installations.save'))?>" method="post"><?=csrf_field()?><input type="hidden" name="_back" value="installations"><input name="id" type="hidden" value="<?=e($edit['id']??'')?>"><div class="form-grid"><div class="field"><label>Projeto *</label><select name="project_id" required><option value="">Selecione...</option><?php foreach($projects as $p):?><option value="<?=e($p['id'])?>" <?=($edit['project_id']??'')==$p['id']?'selected':''?>><?=e($p['title'])?></option><?php endforeach;?></select></div><div class="field"><label>Data e horário *</label><input name="planned_at" type="datetime-local" required value="<?=e(isset($edit['planned_at'])?str_replace(' ','T',substr($edit['planned_at'],0,16)):date('Y-m-d\TH:i'))?>"></div><div class="field"><label>Equipe *</label><input name="team" required value="<?=e($edit['team']??'')?>"></div><div class="field"><label>Endereço de montagem</label><input name="address" value="<?=e($edit['address']??'')?>"></div><div class="field span-2"><label>Checklist (um item por linha)</label><textarea name="checklist" placeholder="Ferramentas conferidas&#10;Peças separadas&#10;Ferragens completas"><?=e($edit['checklist']??'')?></textarea></div><div class="field span-2"><label>Observações</label><textarea name="notes"><?=e($edit['notes']??'')?></textarea></div></div><div class="form-footer"><button class="btn-aurora">Salvar instalação</button><a href="<?=e(url('installations'))?>" class="btn-aurora btn-outline-aurora">Cancelar</a></div></form></div></details><?php endif;?>
<div class="panel"><div class="panel-header"><h2>Agenda de instalações</h2><a href="<?=e(url('calendar'))?>" class="tag">Ver calendário</a></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Projeto</th><th>Data prevista</th><th>Equipe</th><th>Endereço</th><th>Status</th><th>Ações</th></tr></thead><tbody><?php foreach($installations as $i):?><tr><td><strong><?=e($i['project_title'])?></strong><small><?=e($i['customer_name'])?></small></td><td><?=e(date_time_br($i['planned_at']))?></td><td><?=e($i['team'])?></td><td><?=e($i['address']?:'—')?></td><td><?=status_badge($i['status'])?></td><td><div class="table-actions"><?php if(allow(['production'])):?><a class="btn-aurora btn-outline-aurora btn-sm-aurora" href="<?=e(url('installations',['edit'=>$i['id']]))?>#editor"><?=svg_icon('edit',14)?></a><form method="post" action="<?=e(url('installations.status'))?>" style="display:flex;gap:4px"><?=csrf_field()?><input type="hidden" name="id" value="<?=e($i['id'])?>"><select name="status" class="inline-select" aria-label="Situação da instalação"><?php foreach(['scheduled','in_progress','pending','completed'] as $s):?><option value="<?=e($s)?>" <?=$i['status']===$s?'selected':''?>><?=e(label_status($s))?></option><?php endforeach;?></select><button class="btn-aurora btn-sm-aurora">Atualizar</button></form><?php endif;?></div></td></tr><?php endforeach;?><?php if(!$installations):?><tr><td colspan="6" class="empty">Nenhuma instalação agendada.</td></tr><?php endif;?></tbody></table></div></div>
